css:
/* ==== INTERFACE ====
方向：高对比蓝天像素课堂；离散硬边、有限色块与整数阴影表达游戏质感，正文保持平滑清晰，构图适合投影但不限定页面几何。
token --bg：页面底色。
token --text：正文与主要描边色。
token --muted：次要说明。
token --focus：键盘焦点色。
token --accent：增长率与当前强调。
token --accent-2：本金与起始值强调。
token --positive：确认后的增长结果。
token --font-sans：中英正文与控件字体。
token --font-title：中英混排标题字体，英文命中 Press Start 2P、中文命中 Fusion Pixel。
token --font-number：数字与短标签字体。
token --fs-h1/--fs-h2/--fs-lead/--fs-body/--fs-sec/--fs-label/--fs-tick：投影字阶。
token --sp-1/--sp-2/--sp-3/--sp-4/--sp-5/--sp-6：通用间距。
class .nt-title：中英混排页标题；可用内部 [lang="en"] 微调英文短标题。
class .nt-body：中英混排正文。
class .nt-number：数字、百分比与金额；启用等宽表格数字。
class .nt-kicker：短章节标签。
class .nt-formula：公式或关键计算行；不要包裹长段正文。
class .nt-callout：单个重点解释区，内部可用 .nt-callout__label。
class .nt-controls：课堂交互控件区域；按钮用 .nt-button，输入用 .nt-input，当前项加 [aria-pressed="true"] 或 [aria-current="true"]。
class .nt-pixel-art：本地像素图的整数倍展示辅助。
variant opening：深蓝开篇外观，适合短标题与导语。
默认：不设 data-variant；明亮蓝天像素材质，无图片时即为完整背景。
品牌：无。
==== /INTERFACE ==== */

@font-face {
  font-family: "NTF-fusion-pixel";
  src: url("fonts/library/fusion-pixel/face-0.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-press-start-2p";
  src: url("fonts/library/press-start-2p/face-0.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf") format("truetype");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf") format("truetype");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf") format("truetype");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "NTF-jetbrains-mono";
  src: url("fonts/library/jetbrains-mono/face-0.ttf") format("truetype");
  font-weight: 100 800;
  font-style: normal;
  font-display: swap;
}

:root {
  --bg: #8ed1ff;
  --text: #10284d;
  --muted: #31557a;
  --focus: #ffcf31;
  --accent: #ffb703;
  --accent-2: #8b5cf6;
  --positive: #087f5b;
  --danger: #c92a2a;

  --font-sans: "NTF-inter", "NTF-noto-sans-sc", sans-serif;
  --font-title: "NTF-press-start-2p", "NTF-fusion-pixel", "NTF-noto-sans-sc", sans-serif;
  --font-number: "NTF-jetbrains-mono", "NTF-noto-sans-sc", monospace;

  --fs-h1: 62px;
  --fs-h2: 38px;
  --fs-lead: 30px;
  --fs-body: 25px;
  --fs-sec: 21px;
  --fs-label: 18px;
  --fs-tick: 15px;

  --sp-1: 8px;
  --sp-2: 12px;
  --sp-3: 20px;
  --sp-4: 28px;
  --sp-5: 40px;
  --sp-6: 56px;

  color-scheme: light;
  font-family: var(--font-sans);
  color: var(--text);
  background-color: var(--bg);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

html[data-variant="opening"] {
  --bg: #164b91;
  --text: #ffffff;
  --muted: #d7efff;
  --focus: #ffe04b;
  --accent: #ffd43b;
  --accent-2: #c4a7ff;
  --positive: #65e6b4;
  color-scheme: dark;
}

#stage {
  color: var(--text);
  background-color: var(--bg);
  background-image:
    linear-gradient(90deg, transparent 0 7%, rgba(255, 255, 255, 0.58) 7% 18%, rgba(255, 255, 255, 0.84) 18% 30%, rgba(255, 255, 255, 0.58) 30% 40%, transparent 40% 100%),
    linear-gradient(90deg, transparent 0 42%, rgba(255, 255, 255, 0.34) 42% 52%, rgba(255, 255, 255, 0.52) 52% 66%, transparent 66% 100%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.08) 0 72%, rgba(16, 40, 77, 0.07) 72% 74%, rgba(255, 255, 255, 0.16) 74% 100%);
  background-size: 620px 72px, 760px 56px, 100% 100%;
  background-position: 18px 92px, 110px 210px, 0 0;
  background-repeat: repeat-x, repeat-x, no-repeat;
  font-family: var(--font-sans);
}

html[data-variant="opening"] #stage {
  background-image:
    linear-gradient(90deg, transparent 0 12%, rgba(149, 211, 255, 0.20) 12% 26%, rgba(149, 211, 255, 0.34) 26% 37%, transparent 37% 100%),
    linear-gradient(90deg, transparent 0 54%, rgba(255, 255, 255, 0.12) 54% 66%, rgba(255, 255, 255, 0.20) 66% 74%, transparent 74% 100%),
    linear-gradient(180deg, #164b91 0 64%, #123f7d 64% 67%, #0d356c 67% 100%);
  background-size: 680px 72px, 820px 56px, 100% 100%;
  background-position: 24px 96px, 150px 224px, 0 0;
  background-repeat: repeat-x, repeat-x, no-repeat;
}

.nt-title {
  margin: 0;
  color: var(--text);
  font-family: var(--font-title);
  font-size: var(--fs-h1);
  font-weight: 400;
  font-style: normal;
  font-variant-ligatures: none;
  line-height: 1.28;
  letter-spacing: 0;
  text-wrap: balance;
  overflow-wrap: anywhere;
  text-shadow: 4px 4px 0 rgba(255, 255, 255, 0.62);
}

.nt-title[aria-level="2"],
.nt-title.nt-title--small {
  font-size: var(--fs-h2);
  line-height: 1.34;
  text-shadow: 3px 3px 0 rgba(255, 255, 255, 0.58);
}

.nt-title [lang="en"] {
  letter-spacing: 0.025em;
  line-height: 1.38;
}

html[data-variant="opening"] .nt-title {
  text-shadow: 5px 5px 0 #071d3c;
}

.nt-body {
  margin-block: 0;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  font-weight: 450;
  line-height: 1.55;
  letter-spacing: 0.005em;
  overflow-wrap: break-word;
  text-wrap: pretty;
}

.nt-body + .nt-body {
  margin-block-start: 0.72em;
}

.nt-body strong {
  font-weight: 750;
  color: var(--text);
}

.nt-body small,
.nt-caption {
  color: var(--muted);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 500;
  line-height: 1.45;
}

.nt-number {
  font-family: var(--font-number);
  font-weight: 700;
  font-style: normal;
  font-variant-numeric: tabular-nums lining-nums slashed-zero;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.nt-kicker {
  display: inline-block;
  color: #10284d;
  background: var(--focus);
  border: 3px solid #10284d;
  padding: 8px 12px 7px;
  font-family: var(--font-number);
  font-size: var(--fs-label);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  box-shadow: 4px 4px 0 #10284d;
}

.nt-formula {
  display: inline-flex;
  align-items: baseline;
  gap: 0.4em;
  max-width: 100%;
  color: #10284d;
  background: #ffffff;
  border: 4px solid #10284d;
  padding: 16px 20px;
  font-family: var(--font-number);
  font-size: var(--fs-lead);
  font-weight: 700;
  line-height: 1.35;
  font-variant-numeric: tabular-nums lining-nums;
  box-shadow: 8px 8px 0 rgba(16, 40, 77, 0.95);
}

.nt-formula .nt-rate,
.nt-rate {
  color: #8a4f00;
  background: #ffd85a;
  padding-inline: 0.18em;
}

.nt-formula .nt-principal,
.nt-principal {
  color: #4c1d95;
  background: #e5d8ff;
  padding-inline: 0.18em;
}

.nt-formula .nt-result,
.nt-result {
  color: #056344;
  background: #c9f7e5;
  padding-inline: 0.18em;
}

.nt-callout {
  color: var(--text);
  border-inline-start: 12px solid var(--accent);
  border-block: 3px solid var(--text);
  border-inline-end: 3px solid var(--text);
  background: rgba(255, 255, 255, 0.90);
  padding: 20px 24px;
  box-shadow: 7px 7px 0 rgba(16, 40, 77, 0.34);
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  line-height: 1.5;
}

.nt-callout__label {
  display: block;
  margin-block-end: 8px;
  color: #744400;
  font-family: var(--font-number);
  font-size: var(--fs-label);
  font-weight: 800;
  letter-spacing: 0.025em;
}

.nt-controls {
  --surface: rgba(255, 255, 255, 0.92);
  color: #10284d;
  background: var(--surface);
  border: 4px solid #10284d;
  padding: 20px;
  box-shadow: 8px 8px 0 #10284d;
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  line-height: 1.4;
}

.nt-controls .nt-button {
  min-height: 48px;
  color: #10284d;
  background: #ffffff;
  border: 3px solid #10284d;
  border-radius: 0;
  padding: 10px 16px;
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 750;
  line-height: 1.25;
  box-shadow: 4px 4px 0 #10284d;
  cursor: pointer;
}

.nt-controls .nt-button:hover {
  background: #e7f6ff;
}

.nt-controls .nt-button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.nt-controls .nt-button[aria-pressed="true"],
.nt-controls .nt-button[aria-current="true"] {
  background: var(--focus);
}

.nt-controls .nt-input {
  min-height: 48px;
  color: #10284d;
  background: #ffffff;
  border: 3px solid #10284d;
  border-radius: 0;
  padding: 8px 12px;
  font-family: var(--font-number);
  font-size: var(--fs-sec);
  font-weight: 650;
  font-variant-numeric: tabular-nums lining-nums;
}

.nt-controls .nt-button:focus-visible,
.nt-controls .nt-input:focus-visible {
  outline: 5px solid var(--focus);
  outline-offset: 4px;
}

.nt-pixel-art {
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}

::selection {
  color: #10284d;
  background: #ffe04b;
}

@media (prefers-reduced-motion: reduce) {
  .nt-controls .nt-button:active {
    transform: none;
  }
}
